def _payload():
 d=base64.b85decode("".join(_EMBEDDED_B85.split()).encode()); got=hashlib.sha256(d).hexdigest()
 if got!=EMBEDDED_KIT_SHA256: raise SystemExit(f"embedded kit hash mismatch: {got} != {EMBEDDED_KIT_SHA256}")
 return d
def main(argv=None):
 ap=argparse.ArgumentParser(description="Promptless Agent DevTools Stage M2 universal-first installer/update")
 ap.add_argument("--self-check",action="store_true"); ap.add_argument("--target"); ap.add_argument("--preset"); ap.add_argument("--profile",choices=["development","research","analysis","document","general"]); ap.add_argument("--intent"); ap.add_argument("--stack"); ap.add_argument("--plan",action="store_true"); ap.add_argument("--json",action="store_true",dest="json_output")
